    DSU dsu(V);
    int mstWeight = 0, edgesCount = 0;
    for (auto& e : edges) {
        if (dsu.unite(e.u, e.v)) {
            mstWeight += e.weight;
            edgesCount++;
            if (edgesCount == V - 1) break;
        }
    }
    return mstWeight;
}

