        int[] parent, rank;
        DSU(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
            rank = new int[n];
        }
        int find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = find(parent[i]);
        }
        boolean union(int i, int j) {
            int rI = find(i), rJ = find(j);
            if (rI != rJ) {
                if (rank[rI] < rank[rJ]) { int t = rI; rI = rJ; rJ = t; }
                parent[rJ] = rI;
                if (rank[rI] == rank[rJ]) rank[rI]++;
                return true;
            }
            return false;
        }
    }
    public int kruskalMST(int V, List<Edge> edges) {
        Collections.sort(edges);
        DSU dsu = new DSU(V);
        int mstWeight = 0, edgesCount = 0;
        for (Edge e : edges) {
            if (dsu.union(e.u, e.v)) {
                mstWeight += e.weight;
                edgesCount++;
                if (edgesCount == V - 1) break;
            }
        }
        return mstWeight;
    }
}

class DSU {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.rank = new Array(n).fill(0);
  }
  find(i) {
    if (this.parent[i] === i) return i;
    return this.parent[i] = this.find(this.parent[i]);
  }
  union(i, j) {
    let rootI = this.find(i), rootJ = this.find(j);
    if (rootI !== rootJ) {
      if (this.rank[rootI] < this.rank[rootJ]) {
        [rootI, rootJ] = [rootJ, rootI];
      }
      this.parent[rootJ] = rootI;
      if (this.rank[rootI] === this.rank[rootJ]) this.rank[rootI]++;
      return true;
    }
    return false;
  }
}

