    Node(char c, int f) : ch(c), freq(f), left(nullptr), right(nullptr) {}
};

struct cmp {
    bool operator()(Node* a, Node* b) { return a->freq > b->freq; }
};

void buildCodes(Node* root, string code, unordered_map<char, string>& codes) {
    if (!root) return;
    if (root->ch != '\0') codes[root->ch] = code;
    buildCodes(root->left, code + "0", codes);
    buildCodes(root->right, code + "1", codes);
}

unordered_map<char, string> huffmanCoding(const unordered_map<char, int>& freqMap) {
    priority_queue<Node*, vector<Node*>, cmp> pq;
    for (auto& p : freqMap) pq.push(new Node(p.first, p.second));
    while (pq.size() > 1) {
        Node* l = pq.top(); pq.pop();
        Node* r = pq.top(); pq.pop();
        Node* parent = new Node('\0', l->freq + r->freq);
        parent->left = l; parent->right = r;
        pq.push(parent);
    }
    unordered_map<char, string> codes;
    buildCodes(pq.top(), "", codes);
    return codes;
}

