public class Solution {
    public Map<Character, String> huffmanCoding(Map<Character, Integer> freqMap) {
        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (Map.Entry<Character, Integer> entry : freqMap.entrySet()) {
            pq.add(new Node(entry.getKey(), entry.getValue()));
        }
        while (pq.size() > 1) {
            Node l = pq.poll(), r = pq.poll();
            Node parent = new Node('\0', l.freq + r.freq);
            parent.left = l; parent.right = r;
            pq.add(parent);
        }
        Map<Character, String> codes = new HashMap<>();
        buildCodes(pq.peek(), "", codes);
        return codes;
    }
    private void buildCodes(Node node, String code, Map<Character, String> codes) {
        if (node == null) return;
        if (node.ch != '\0') codes.put(node.ch, code);
        buildCodes(node.left, code + "0", codes);
        buildCodes(node.right, code + "1", codes);
    }
}

function huffmanCoding(freqMap) {
  const nodes = Object.entries(freqMap).map(([ch, freq]) => ({ ch, freq, left: null, right: null }));
  while (nodes.length > 1) {
    nodes.sort((a, b) => a.freq - b.freq);
    const l = nodes.shift();
    const r = nodes.shift();
    nodes.push({ ch: null, freq: l.freq + r.freq, left: l, right: r });
  }
  const codes = {};
  function buildCodes(node, code = '') {
    if (!node) return;
    if (node.ch) codes[node.ch] = code;
    buildCodes(node.left, code + '0');
    buildCodes(node.right, code + '1');
  }
  buildCodes(nodes[0]);
  return codes;
}

def merge(intervals: list[list[int]]) -> list[list[int]]:
    intervals.sort(key=lambda x: x[0])
    merged = []
    for interval in intervals:
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

