function primMST(V, adj) {
  const visited = new Array(V).fill(false);
  let mstWeight = 0;
  const key = new Array(V).fill(Infinity);
  key[0] = 0;
  for (let i = 0; i < V; i++) {
    let u = -1;
    for (let j = 0; j < V; j++) {
      if (!visited[j] && (u === -1 || key[j] < key[u])) u = j;
    }
    visited[u] = true;
    mstWeight += key[u];
    for (const [v, w] of adj[u]) {
      if (!visited[v] && w < key[v]) key[v] = w;
    }
  }
  return mstWeight;
}
